import{z as i,x as s,o as r,c as f,q as t,j as A,D as e,d as B,s as o,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Offner 中继成像","description":"","frontmatter":{"title":"Offner 中继成像","date":"2026-09-27T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/offner-relay.md","filePath":"litho/offner-relay.md","lastUpdated":1791413859000}'),d={name:"litho/offner-relay.md"};function p(m,E,D,c,h,F){const n=s("Mermaid");return r(),f("div",null,[E[2]||(E[2]=t('<h1 id="offner-中继成像" tabindex="-1">Offner 中继成像 <a class="header-anchor" href="#offner-中继成像" aria-label="Permalink to &quot;Offner 中继成像&quot;">​</a></h1><div class="epigraph"><p>环形镜绕着环形像走：Offner 用两块同球心的球面镜，把「场曲」这个大反派直接请进了系统设定。</p><footer>—— 据 Offner 专利 US 3,748,015 (1973)；光谱仪器与 EUV 探测成像的应用文献</footer></div><p><a href="/litho/zone-plate-optics">波带片光学</a>用衍射救场，本课的替代路线是反射几何：<strong>Offner 中继</strong>——共球心的凸/凹双球面镜组成的 1:1 中继成像系统。它像差极低、色差为零、结构极简，是光谱仪、EUV 掩模探测与早期投影光刻实验的经典选择。本课不做反射镜镀膜的一般理论。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>折射透镜的两宗罪在深紫外与宽光谱场景爆炸：色差（折射率随波长变）与材料吸收（193nm 以下石英吃光）。反射镜天然无色差、无吸收——但单球面镜的球差与彗差让离轴成像一团糟。缺口：<strong>一个用两块普通球面镜就几乎消尽像差的成像系统</strong>。Offner 的洞察：不要矫正场曲，让物面与像面共处同一个球面。</p><p><span class="marginnote">术语翻译：Offner 单元 = 凸面次镜（convex secondary）置于凹面主镜（concave primary）的曲率中心附近，两者共球心；环形视场（annular field）= 物/像位于以共同球心为圆心的圆弧带上，像差在此带上自消。</span></p><p><span class="marginnote">数字实例：典型参数——主镜曲率半径 R1=300mm、次镜 R2=150mm（约 R1/2）、放大率 1:1。在 20mm 宽的环形带上，波前误差可压到 λ/50 以下；同参数单球面镜的边缘球差则比波长大百倍——两块普通镜子的差距全在几何布局。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>布局三步：主镜（凹）+ 次镜（凸，凸面朝主镜）共球心安置；物放在环带一侧、像 1:1 成在环带另一侧；工作光束在两镜间的环形空域折叠传播。使用变体：作为<strong>光谱仪成像镜</strong>（光栅 + Offner 把不同波长成像到探测器不同列，Offner-Chrisp 型是手机光谱模块的常见配置）；作为<strong>投影中继</strong>（掩模-晶圆 1:1 投影，早期投影光刻与 EUV 掩模缺陷探测（MARS 类工具）用它把掩模图案成像到传感器）。</p>',9)),(r(),A(l,null,{default:e(()=>[o(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%87%B9%E4%B8%BB%E9%95%9C%20%2B%20%E5%87%B8%E6%AC%A1%E9%95%9C%E5%85%B1%E7%90%83%E5%BF%83%22%5D%20--%3E%20B%5B%22%E7%89%A9%E5%9C%A8%E7%8E%AF%E5%BD%A2%E5%B8%A6%E4%B8%80%E4%BE%A7%22%5D%0A%20%20B%20--%3E%20C%5B%22%E7%8E%AF%E5%BD%A2%E7%A9%BA%E5%9F%9F%E6%8A%98%E5%8F%A0%E5%85%89%E8%B7%AF%22%5D%0A%20%20C%20--%3E%20D%5B%221%3A1%20%E6%88%90%E5%83%8F%E5%9C%A8%E5%8F%A6%E4%B8%80%E4%BE%A7%E7%8E%AF%E5%B8%A6%22%5D%0A%20%20D%20--%3E%20E%7B%22%E7%94%A8%E9%80%94%22%7D%0A%20%20E%20--%3E%7C%22%E5%8A%A0%E5%85%89%E6%A0%85%22%7C%20F%5B%22%E5%85%89%E8%B0%B1%E4%BB%AA%3A%20%E6%B3%A2%E9%95%BF%E2%86%92%E5%88%97%E6%88%90%E5%83%8F%22%5D%0A%20%20E%20--%3E%7C%22%E6%8E%A9%E6%A8%A1%E2%86%92%E4%BC%A0%E6%84%9F%E5%99%A8%22%7C%20G%5B%22EUV%20%E6%8E%A9%E6%A8%A1%E7%BC%BA%E9%99%B7%E6%8E%A2%E6%B5%8B%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：像「同心圆跑道」——物与像站在同一条圆弧跑道的两端，光沿着跑道内侧反弹两下正好跑到像的位置；因为物、像、镜共一个球心，「跑偏」的像差在几何上没有发生的余地。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"消像差机制：整个系统的对称性是「关于共同球心的同心性」——主镜产生的球差被次镜反向球差精确抵消（两镜球差符号相反、大小由曲率比调配），彗差与像散因环形视场的对称位置同消，场曲则以「像面本来就是弧面」的方式被吸收——把反派写进剧本就没有反派。色差机制：反射率与波长无关，零色差是「天生」的，这正是它在宽谱（光谱仪）与深紫外（EUV 检测）立足的根。残留像差：环形带有限宽度内的像散与高阶球差随带宽增加，放大率偏离 1:1 会破坏完美抵消——Offner 几乎总在 1:1 附近工作就是这个原因。",-1)),(r(),A(l,null,{default:e(()=>[o(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E5%83%8F%E5%B7%AE%E4%B8%BA%E4%BD%95%E6%B6%88%3F%22%7D%20--%3E%20R%5B%22%E4%B8%A4%E9%95%9C%E7%90%83%E5%B7%AE%E5%8F%8D%E5%90%91%E4%BA%92%E6%8A%B5%22%5D%0A%20%20R%20--%3E%20S%5B%22%E7%8E%AF%E5%BD%A2%E5%AF%B9%E7%A7%B0%E6%B6%88%E5%BD%97%E5%B7%AE%E5%83%8F%E6%95%A3%22%5D%0A%20%20S%20--%3E%20T%5B%22%E5%9C%BA%E6%9B%B2%E8%A2%AB%E5%BC%A7%E5%BD%A2%E5%83%8F%E9%9D%A2%E5%90%B8%E6%94%B6%22%5D%0A%20%20U%7B%22%E8%89%B2%E5%B7%AE%E4%B8%BA%E4%BD%95%E4%B8%BA%E9%9B%B6%3F%22%7D%20--%3E%20V%5B%22%E5%8F%8D%E5%B0%84%E7%8E%87%E4%B8%8E%E6%B3%A2%E9%95%BF%E6%97%A0%E5%85%B3%22%5D%0A%20%20V%20--%3E%20W%5B%22%E5%AE%BD%E8%B0%B1%2F%E6%B7%B1%E7%B4%AB%E5%A4%96%E7%AB%8B%E8%B6%B3%E4%B9%8B%E6%9C%AC%22%5D%0A%20%20X%7B%22%E4%B8%BA%E4%BD%95%E5%BF%85%E9%A1%BB%201%3A1%3F%22%7D%20--%3E%20Y%5B%22%E5%81%8F%E7%A6%BB%E5%8D%B3%E7%A0%B4%E5%9D%8F%E6%8A%B5%E6%B6%88%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<p><span class="marginnote">常见误区：把 Offner 当「望远镜」——它是中继（relay）系统，物像 1:1 且都在有限远；另一误区是「球面镜随便放都行」——次镜必须放在主镜曲率中心附近，偏移几个毫米像差立刻抬头，它的「简单」是布局严格意义上的简单。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>视场边界：像质保证只存在于环形带内，带外无解——大面积成像靠扫描（物/像沿环带扫过），这也是 Offner 光谱仪「推扫」成像的由来。放大率边界：1:1 附近的小偏离（±10%）可调，大倍率直接换系统。它没有成为主流光刻投影光学的原因：1:1 意味着掩模与晶圆同尺寸——掩模做不到晶圆级的精度，缩小投影（4:1，现代步进与扫描机）才是量产路线；Offner 退守检测、光谱与特殊成像。与<a href="/litho/actinic-blank-inspect">掩模缺陷的 EUV 探测</a>的呼应：Actinic 检测需要 EUV 波长的成像光学，Offner 类双镜系统是当前 actinic review 工具（如 Lasertec ACTIS）的光学骨架候选。</p><p><span class="marginnote">直觉类比：Offner 之于投影光刻像「等身镜」——照出来跟你一样大（1:1）；镜子照人无色差、无畸变（反射几何），但你不能指望镜子把人变小（无缩小倍率），所以「拍照比人小四倍」的现代照相机（缩小投影光刻）成了主流，等身镜留给了「要看原尺寸细节」的质检台（掩模检测）。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Offner = 共球心凸/凹双球面镜的 1:1 环形成像中继。</li><li>消像差靠同心对称性互抵，场曲被弧形像面吸收；零色差天生。</li><li>1:1 限制让它让位缩小投影，退守光谱仪与 EUV 掩模检测。</li><li>出处：Offner US 3,748,015；Attwood 教材；Lasertec ACTIS actinic 检测技术资料。</li></ul>',6))])}const _=i(d,[["render",p]]);export{u as __pageData,_ as default};
